const MEMCHAT_ALARM_DATA_URL = "data:audio/mpeg;base64,";
// DOM/audio only; no storage, API credentials, or site-controlled sources.
let orderAudioPlayer = null;
let orderAudioLastId = '';
let orderAudioEpoch = 0;
let orderAudioStarting = false;
chrome.runtime.onMessage.addListener((message, sender, reply) => {
    if (message?.target !== 'memchat-offscreen' || sender.id !== chrome.runtime.id || sender.tab
        || (sender.url && sender.url !== chrome.runtime.getURL('worker.js'))) return false;
    if (message.type === 'memchat:audio-stop') {
        orderAudioEpoch++;
        orderAudioStarting = false;
        orderAudioPlayer?.pause();
        if (orderAudioPlayer) orderAudioPlayer.currentTime = 0;
        reply({ ok: true });
        return false;
    }
    if (message.type !== 'memchat:audio-play') return false;
    if (!orderAudioPlayer) { orderAudioPlayer = new Audio(MEMCHAT_ALARM_DATA_URL); orderAudioPlayer.preload = 'auto'; }
    if (orderAudioStarting || !orderAudioPlayer.paused || (message.id && message.id === orderAudioLastId)) { reply({ ok: true, coalesced: true }); return false; }
    orderAudioLastId = message.id || '';
    orderAudioPlayer.currentTime = 0;
    const epoch = ++orderAudioEpoch;
    orderAudioStarting = true;
    Promise.resolve().then(() => epoch === orderAudioEpoch ? orderAudioPlayer.play() : undefined).then(() => {
        if (epoch === orderAudioEpoch) orderAudioStarting = false;
        reply({ ok: true });
    }, () => {
        if (epoch === orderAudioEpoch) { orderAudioStarting = false; orderAudioLastId = ''; }
        reply({ ok: false, error: 'Звук расширения недоступен' });
    });
    return true;
});
